//! Generation driver: turns the typed [`gh_workflow::Workflow`] generators into
//! `.github/workflows/*.yaml` on disk (or, with `--check`, verifies the
//! committed files match).

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};
use gh_workflow::Workflow;

use crate::workflows::{cargo_tests, ci, size_gate, vars, wasm_pack_tests, webview_tests};

/// First line of every generated file. The stale-file cleaner matches on this
/// prefix so hand-written YAML is left untouched.
pub const PREAMBLE: &str = "# @generated by `cargo xtask workflows`";

pub struct RunArgs {
    pub check: bool,
}

/// One generator: `(module segment, output filename, fn)`.
struct Generator {
    module: &'static str,
    filename: &'static str,
    build: fn() -> Workflow,
}

const GENERATORS: &[Generator] = &[
    Generator { module: "ci", filename: "ci.yaml", build: ci::workflow },
    Generator {
        module: "cargo_tests",
        filename: "cargo-tests.reusable.yaml",
        build: cargo_tests::workflow,
    },
    Generator {
        module: "size_gate",
        filename: "size-gate.reusable.yaml",
        build: size_gate::workflow,
    },
    Generator {
        module: "wasm_pack_tests",
        filename: "wasm-pack-tests.reusable.yaml",
        build: wasm_pack_tests::workflow,
    },
    Generator {
        module: "webview_tests",
        filename: "webview-tests.reusable.yaml",
        build: webview_tests::workflow,
    },
];

/// Resolves `<repo>/.github/workflows` from the compile-time manifest path,
/// independent of the process cwd.
///
/// `CARGO_MANIFEST_DIR` = `<repo>/baml_language/crates/tools_xtask`; the repo
/// root is three levels up.
#[must_use]
pub fn workflows_dir() -> PathBuf {
    let repo_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("repo root is 3 levels above tools_xtask manifest");
    let dir = repo_root.join(".github/workflows");
    assert!(dir.is_dir(), "expected {} to exist", dir.display());
    dir
}

/// The two-line `@generated` banner for `module`.
fn disclaimer(module: &str) -> String {
    format!(
        "{PREAMBLE} from tools_xtask::workflows::{module} -- DO NOT EDIT.\n\
         # Rebuild with: cd baml_language && cargo xtask workflows"
    )
}

/// Renders the full file contents for one generator: secrets-inherit transform,
/// then `[disclaimer, yaml].join("\n")`.
fn render(g: &Generator) -> Result<String> {
    let workflow = (g.build)();
    let yaml = workflow
        .to_string()
        .map_err(|e| anyhow::anyhow!("serializing {}: {e:?}", g.module))?;
    let yaml = fix_arbitrary_precision_numbers(&yaml);
    let yaml = apply_secrets_inherit(&yaml);
    let yaml = apply_write_all(&yaml);
    let yaml = apply_matrix_timeout(&yaml);
    // Validate the emitted YAML re-parses (catches transform mistakes).
    serde_yaml::from_str::<serde_yaml::Value>(&yaml)
        .with_context(|| format!("generated YAML for {} does not parse", g.module))?;
    Ok([disclaimer(g.module), yaml].join("\n"))
}

/// Collapses serde_json's arbitrary-precision number representation back into
/// plain YAML scalars.
///
/// The workspace pins `serde_json` with the `arbitrary_precision` feature,
/// under which `serde_json::Value::Number` serializes (through serde_yaml) as a
/// nested map `{ "$serde_json::private::Number": "<digits>" }` instead of a
/// bare number. Every numeric `env:` / `with:` value built from a Rust integer
/// (e.g. `CARGO_INCREMENTAL: 0`, `fetch-depth: 0`) hits this. We rewrite each
/// such two-line block:
///
/// ```text
///   key:
///     $serde_json::private::Number: '0'
/// ```
///
/// into `key: 0`. Numbers stored in real typed fields (e.g. `timeout-minutes`)
/// are unaffected because they never become a `serde_json::Value`.
fn fix_arbitrary_precision_numbers(yaml: &str) -> String {
    const MARKER: &str = "$serde_json::private::Number: ";
    let lines: Vec<&str> = yaml.lines().collect();
    let mut out: Vec<String> = Vec::with_capacity(lines.len());
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        // A wrapped number is the line AFTER a `key:` (empty value) line.
        if i + 1 < lines.len() {
            let next = lines[i + 1];
            let next_trim = next.trim_start();
            if next_trim.starts_with(MARKER) && line.trim_end().ends_with(':') {
                let digits = next_trim[MARKER.len()..].trim().trim_matches('\'');
                out.push(format!("{} {digits}", line.trim_end()));
                i += 2;
                continue;
            }
        }
        out.push(line.to_string());
        i += 1;
    }
    let mut result = out.join("\n");
    if yaml.ends_with('\n') {
        result.push('\n');
    }
    result
}

/// Rewrites the [`vars::SECRETS_INHERIT_SENTINEL`] `with:` marker into a
/// sibling `secrets: inherit`.
///
/// The fork cannot express `secrets: inherit` through its public API, so
/// [`vars::call_reusable_inherit`] injects `with: { <sentinel>: true }` and we
/// patch the serialized YAML here. For each `with:` block that carries the
/// sentinel:
///   * if the sentinel is the only child -> the entire `with:` block becomes
///     `secrets: inherit`;
///   * if there are real inputs too -> the sentinel line is dropped and a
///     `secrets: inherit` sibling is appended right after the `with:` block, at
///     the `with:` indentation.
fn apply_secrets_inherit(yaml: &str) -> String {
    let lines: Vec<&str> = yaml.lines().collect();
    let sentinel_line = format!("{}: true", vars::SECRETS_INHERIT_SENTINEL);
    let mut out: Vec<String> = Vec::with_capacity(lines.len());

    let indent_of = |line: &str| line.chars().take_while(|c| *c == ' ').count();

    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if line.trim_start() != "with:" {
            out.push(line.to_string());
            i += 1;
            continue;
        }

        let with_indent = indent_of(line);
        // Gather the `with:` child block (all subsequent lines indented deeper).
        let mut j = i + 1;
        while j < lines.len()
            && (lines[j].trim().is_empty() || indent_of(lines[j]) > with_indent)
        {
            j += 1;
        }
        let block = &lines[i + 1..j];
        let has_sentinel = block.iter().any(|l| l.trim_start() == sentinel_line);

        if !has_sentinel {
            // Untouched `with:` block.
            out.push(line.to_string());
            for &b in block {
                out.push(b.to_string());
            }
            i = j;
            continue;
        }

        let real_children: Vec<&&str> = block
            .iter()
            .filter(|l| !l.trim().is_empty() && l.trim_start() != sentinel_line)
            .collect();
        let with_indent_str = " ".repeat(with_indent);

        if real_children.is_empty() {
            // Sentinel was the only input -> replace whole block.
            out.push(format!("{with_indent_str}secrets: inherit"));
        } else {
            out.push(line.to_string());
            for &b in block {
                if b.trim_start() == sentinel_line {
                    continue;
                }
                out.push((*b).to_string());
            }
            out.push(format!("{with_indent_str}secrets: inherit"));
        }
        i = j;
    }

    let mut result = out.join("\n");
    if yaml.ends_with('\n') {
        result.push('\n');
    }
    result
}

/// Collapses a `permissions:` block whose children are exactly the 10 modeled
/// scopes set to `write` (i.e. the block emitted by [`vars::permissions_write_all`])
/// into the `permissions: write-all` scalar.
///
/// The fork's `Permissions` struct cannot model `write-all`, nor the
/// attestations / discussions / models / repository-projects / security-events
/// scopes that `write-all` grants. Emitting the 10-scope subset would silently
/// narrow the GITHUB_TOKEN, so we restore the original `write-all` here. Keyed on
/// the exact set [`vars::WRITE_ALL_SCOPES`] = `write`, which no other job emits.
fn apply_write_all(yaml: &str) -> String {
    let lines: Vec<&str> = yaml.lines().collect();
    let mut out: Vec<String> = Vec::with_capacity(lines.len());
    let indent_of = |line: &str| line.chars().take_while(|c| *c == ' ').count();

    let want: std::collections::BTreeSet<String> = vars::WRITE_ALL_SCOPES
        .iter()
        .map(|s| format!("{s}: write"))
        .collect();

    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if line.trim_start() != "permissions:" {
            out.push(line.to_string());
            i += 1;
            continue;
        }

        let perm_indent = indent_of(line);
        // Gather the child block (subsequent lines indented deeper).
        let mut j = i + 1;
        while j < lines.len()
            && (lines[j].trim().is_empty() || indent_of(lines[j]) > perm_indent)
        {
            j += 1;
        }
        let block = &lines[i + 1..j];
        let children: std::collections::BTreeSet<String> = block
            .iter()
            .filter(|l| !l.trim().is_empty())
            .map(|l| l.trim().to_string())
            .collect();

        if children == want {
            out.push(format!("{}permissions: write-all", " ".repeat(perm_indent)));
        } else {
            out.push(line.to_string());
            for &b in block {
                out.push(b.to_string());
            }
        }
        i = j;
    }

    let mut result = out.join("\n");
    if yaml.ends_with('\n') {
        result.push('\n');
    }
    result
}

/// Rewrites the [`vars::TIMEOUT_MATRIX_SENTINEL`] `timeout-minutes:` value into
/// the [`vars::TIMEOUT_MATRIX_EXPR`] matrix expression.
///
/// The fork's `timeout_minutes: Option<u32>` field cannot hold a templated
/// expression, so jobs needing `timeout-minutes: ${{ matrix.timeout }}` emit the
/// sentinel integer and we restore the expression here.
fn apply_matrix_timeout(yaml: &str) -> String {
    let sentinel = vars::TIMEOUT_MATRIX_SENTINEL.to_string();
    let mut out: Vec<String> = Vec::new();
    for line in yaml.lines() {
        let trimmed = line.trim_start();
        if trimmed == format!("timeout-minutes: {sentinel}") {
            let indent = &line[..line.len() - trimmed.len()];
            out.push(format!(
                "{indent}timeout-minutes: {}",
                vars::TIMEOUT_MATRIX_EXPR
            ));
        } else {
            out.push(line.to_string());
        }
    }
    let mut result = out.join("\n");
    if yaml.ends_with('\n') {
        result.push('\n');
    }
    result
}

/// Deletes only files in `dir` whose contents start with [`PREAMBLE`].
fn remove_generated_workflows(dir: &Path) -> Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let path = entry.path();
        if fs::read_to_string(&path).is_ok_and(|c| c.starts_with(PREAMBLE)) {
            fs::remove_file(&path)?;
        }
    }
    Ok(())
}

#[allow(clippy::needless_pass_by_value)]
pub fn run(args: RunArgs) -> Result<()> {
    let out = workflows_dir();

    if args.check {
        let mut drifted = Vec::new();
        for g in GENERATORS {
            let want = render(g)?;
            let path = out.join(g.filename);
            let have = fs::read_to_string(&path).unwrap_or_default();
            if have != want {
                drifted.push(g.filename);
            }
        }
        if !drifted.is_empty() {
            bail!(
                "generated workflows are out of date: {}. Run `cd baml_language && cargo xtask workflows`.",
                drifted.join(", ")
            );
        }
        return Ok(());
    }

    // Render everything first so a failure leaves the tree untouched.
    let rendered: Vec<(PathBuf, String)> = GENERATORS
        .iter()
        .map(|g| render(g).map(|c| (out.join(g.filename), c)))
        .collect::<Result<_>>()?;

    remove_generated_workflows(&out)?;
    for (path, content) in rendered {
        fs::write(&path, content)
            .with_context(|| format!("writing {}", path.display()))?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::workflows::vars;
    use gh_workflow::{Input, Workflow};

    fn render_test(workflow: &Workflow) -> String {
        let yaml = workflow.to_string().unwrap();
        let yaml = fix_arbitrary_precision_numbers(&yaml);
        apply_secrets_inherit(&yaml)
    }

    #[test]
    fn numbers_are_collapsed() {
        let wf = vars::standard_env(Workflow::default().name("t"));
        let out = render_test(&wf);
        assert!(out.contains("CARGO_INCREMENTAL: 0"), "{out}");
        assert!(!out.contains("$serde_json"), "{out}");
        assert!(serde_yaml::from_str::<serde_yaml::Value>(&out).is_ok());
    }

    #[test]
    fn secrets_inherit_sole_with() {
        // call_reusable_inherit with no real inputs -> `secrets: inherit`,
        // no `with:` block.
        let job = vars::call_reusable_inherit("./.github/workflows/x.reusable.yaml");
        let wf = Workflow::default().name("t").add_job("call", job);
        let out = render_test(&wf);
        assert!(out.contains("secrets: inherit"), "{out}");
        assert!(!out.contains("with:"), "{out}");
        assert!(!out.contains(vars::SECRETS_INHERIT_SENTINEL), "{out}");
        assert!(serde_yaml::from_str::<serde_yaml::Value>(&out).is_ok());
    }

    #[test]
    fn secrets_inherit_with_real_inputs() {
        let job = vars::call_reusable_inherit_with(
            "./.github/workflows/docs.reusable.yaml",
            Input::default().add("docs_changed", "${{ needs.x.outputs.docs }}"),
        );
        let wf = Workflow::default().name("t").add_job("docs", job);
        let out = render_test(&wf);
        assert!(out.contains("secrets: inherit"), "{out}");
        assert!(out.contains("docs_changed:"), "{out}");
        assert!(out.contains("with:"), "{out}");
        assert!(!out.contains(vars::SECRETS_INHERIT_SENTINEL), "{out}");
        assert!(serde_yaml::from_str::<serde_yaml::Value>(&out).is_ok());
    }
}
